// In AppComponent template:
// Add <app-generic-list> here

import { Component, Input } from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-generic-list',
  template: '<div *ngFor="let item of items">{{item[displayProperty]}}</div>'
})
export class GenericListComponent<T> {
  @Input() items: T[];
  @Input() displayProperty: keyof T;
}

interface Item {
  id: number;
  name: string;
  description: string;
}

@Component({
  selector: 'app-root',
  template: `
    <app-generic-list 
      [items]="sampleItems" 
      [displayProperty]="'name'">
    </app-generic-list>
  `
})
export class AppComponent {
  sampleItems: Item[] = [
    { id: 1, name: 'Item One', description: 'First item' },
    { id: 2, name: 'Item Two', description: 'Second item' },
    { id: 3, name: 'Item Three', description: 'Third item' }
  ];
}
